  </style>
</head>
<body>
  <canvas id="canvas" width="800" height="800"></canvas>
  <div class="gui-container"></div>

  <!-- dat.gui CDN -->
  <script src="https://cdnjs.cloudflare.com/ajax/libs/dat-gui/0.7.9/dat.gui.min.js"></script>

  <script>
    // Canvas setup
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    // Configuration object
    const config = {
      // Growth settings
      neuronCount: 4,
      branchSpeed: 1,
      maxBranchDepth: 6,
      branchSplitChance: 0.4,
      branchCurvature: 0.5,
      maxBranchLength: 100,

      // Synapse settings
      synapseThreshold: 40,
      synapseGlow: 15,

      // Pulse settings
      pulseSpeed: 3,
      pulseFrequency: 0.02,
      pulseBrightness: 1,

      // Visual settings
      backgroundColor: '#05070f',
      branchColor: '#00e5ff',
      accentBranchColor: '#d6ff00',
      synapseColor: '#ff2bd6',
      pulseColor: '#fff36a',
      pulseSpeed: 3,
      pulseFrequency: 0.02,
      pulseBrightness: 1,

      // Buttons
      regenerateNetwork: () => regenerate(),
      clearCanvas: () => clear(),
      pauseResume: () => togglePause()
    };

    // State
    let neurons = [];
    let branches = [];
    let synapses = [];
    let pulses = [];
    let isPaused = false;
    let animationId = null;

    // Seed random for reproducibility
    function seededRandom(seed) {
      const x = Math.sin(seed) * 10000;
      return x - Math.floor(x);
    }

    // Generate random position near center
    function randomNeuronPosition() {
      const angle = Math.random() * Math.PI * 2;
      const dist = Math.random() * 80;
      return {
        x: width / 2 + Math.cos(angle) * dist,
        y: height / 2 + Math.sin(angle) * dist
      };
    }

    // Neuron class
    class Neuron {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.radius = 4 + Math.random() * 4;
      }
    }

    // Branch class
    class Branch {
      constructor(startX, startY, angle, depth, parent) {
        this.startX = startX;
        this.startY = startY;
        this.x = startX;
        this.y = startY;
        this.angle = angle;
        this.depth = depth;
        this.parent = parent;
        this.length = 0;
        this.maxLength = config.maxBranchLength * (0.7 + Math.random() * 0.6);
        this.speed = config.branchSpeed * (0.8 + Math.random() * 0.4);
        this.width = Math.max(1, (6 - depth) * 0.8);
        this.finished = false;
        this.targetX = startX;
        this.targetY = startY;
        this.controlX = startX;
        this.controlY = startY;
      }

      update() {
        if (this.finished) return true;

        this.length += this.speed;

        if (this.length >= this.maxLength) {
          this.length = this.maxLength;
          this.finished = true;
        }

        // Calculate target position with curvature
        const curvature = (Math.random() - 0.5) * config.branchCurvature * 0.5;
        const targetAngle = this.angle + curvature;

        this.targetX = this.x + Math.cos(targetAngle) * this.length;
        this.targetY = this.y + Math.sin(targetAngle) * this.length;

        // Control point for quadratic curve
        const midX = (this.x + this.targetX) / 2;
        const midY = (this.y + this.targetY) / 2;
        const controlAngle = this.angle + curvature * 0.7;
        this.controlX = midX + Math.cos(controlAngle) * this.length * 0.3;
        this.controlY = midY + Math.sin(controlAngle) * this.length * 0.3;

        return true;
      }
    }

    // Synapse class
    class Synapse {
      constructor(branch1, branch2) {
        this.branch1 = branch1;
        this.branch2 = branch2;
        this.x = (branch1.x + branch2.x) / 2;
        this.y = (branch1.y + branch2.y) / 2;
        this.pulsePhase = Math.random() * Math.PI * 2;
      }

      draw(time) {
        const glow = config.synapseGlow * (0.7 + 0.3 * Math.sin(time * 2 + this.pulsePhase));
        ctx.beginPath();
        ctx.arc(this.x, this.y, 2, 0, Math.PI * 2);
        ctx.fillStyle = config.synapseColor;
        ctx.shadowColor = config.synapseColor;
        ctx.shadowBlur = glow;
        ctx.fill();
        ctx.shadowBlur = 0;
      }
    }

    // Pulse class
    class Pulse {
      constructor(synapse) {
        this.synapse = synapse;
        this.progress = 0;
        this.speed = config.pulseSpeed * (0.5 + Math.random() * 0.5);
        this.active = true;
      }

      update() {
        this.progress += this.speed;
        if (this.progress >= 1) {
          this.active = false;
          return false;
        }
        return true;
      }

      draw() {
        if (!this.active) return;

        const t = this.progress;
        const x = (1 - t) * this.synapse.branch1.x + t * this.synapse.branch2.x;
        const y = (1 - t) * this.synapse.branch1.y + t * this.synapse.branch2.y;

        const brightness = config.pulseBrightness * (1 - t * 0.3);
        const size = 2 + brightness * 2;

        ctx.beginPath();
        ctx.arc(x, y, size, 0, Math.PI * 2);
        ctx.fillStyle = config.pulseColor;
        ctx.shadowColor = config.pulseColor;
        ctx.shadowBlur = 10;
        ctx.globalAlpha = brightness;
        ctx.fill();
        ctx.globalAlpha = 1;
        ctx.shadowBlur = 0;
      }
    }

    // Initialize neurons
    function initNeurons() {
      neurons = [];
      const count = Math.floor(config.neuronCount);
      for (let i = 0; i < count; i++) {
        neurons.push(new Neuron(randomNeuronPosition().x, randomNeuronPosition().y));
      }
    }

    // Regenerate network
    function regenerate() {
      clear();
      initNeurons();
      growBranches();
    }

    // Clear canvas
    function clear() {
      neurons = [];
      branches = [];
      synapses = [];
      pulses = [];
      ctx.clearRect(0, 0, width, height);
    }

    // Toggle pause
    function togglePause() {
      isPaused = !isPaused;
    }

    // Grow branches recursively
    function growBranches() {
      branches = [];

      // Start branches from each neuron
      neurons.forEach(neuron => {
        const startAngle = Math.random() * Math.PI * 2;
        branches.push(new Branch(neuron.x, neuron.y, startAngle, 0, null));
      });

      // Start animation loop for growth
      let growing = true;
      const growthInterval = setInterval(() => {
        if (isPaused) return;

        let allFinished = true;
        const newBranches = [];

        branches.forEach(branch => {
          if (branch.update()) {
            allFinished = false;

            // Check for split
            if (branch.depth < config.maxBranchDepth &&
                Math.random() < config.branchSplitChance &&
                !branch.finished) {
              const splitAngle = branch.angle + (Math.random() - 0.5) * 0.8;
              newBranches.push(new Branch(branch.x, branch.y, splitAngle, branch.depth + 1, branch));
            }
          }
        });

        branches = branches.concat(newBranches);
        checkSynapses();

        if (allFinished) {
          clearInterval(growthInterval);
          startPulseAnimation();
        }
      }, 16);
    }

    // Check for synapses between branches
    function checkSynapses() {
      for (let i = 0; i < branches.length; i++) {
        for (let j = i + 1; j < branches.length; j++) {
          const b1 = branches[i];
          const b2 = branches[j];
          const dist = Math.hypot(b1.x - b2.x, b1.y - b2.y);

          if (dist < config.synapseThreshold && dist > 5) {
            // Check for existing synapse
            const exists = synapses.some(s =>
              (s.branch1 === b1 && s.branch2 === b2) ||
              (s.branch1 === b2 && s.branch2 === b1)
            );

            if (!exists) {
              synapses.push(new Synapse(b1, b2));
            }
          }
        }
      }
    }

    // Start pulse animation
    function startPulseAnimation() {
      let lastPulse = 0;
      let pulseInterval = null;

      pulseInterval = setInterval(() => {
        if (isPaused || synapses.length === 0) return;

        const now = Date.now();
        if (now - lastPulse > 1000 / config.pulseFrequency) {
          const randomSynapse = synapses[Math.floor(Math.random() * synapses.length)];
          pulses.push(new Pulse(randomSynapse));
          lastPulse = now;
        }
      }, 50);

      // Store interval ID to clear if needed
      pulses.pulseInterval = pulseInterval;
    }

    // Render function
    function render(time) {
      // Background
      ctx.fillStyle = config.backgroundColor;
      ctx.fillRect(0, 0, width, height);

      // Draw background glow
      const gradient = ctx.createRadialGradient(
        width / 2, height / 2, 0,
        width / 2, height / 2, 400
      );
      gradient.addColorStop(0, 'rgba(16, 26, 58, 0.6)');
      gradient.addColorStop(1, 'rgba(5, 7, 15, 0)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, width, height);

      // Draw grid (optional)
      ctx.strokeStyle = 'rgba(0, 229, 255, 0.05)';
      ctx.lineWidth = 1;
      for (let x = 0; x < width; x += 50) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
      }
      for (let y = 0; y < height; y += 50) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      // Draw branches
      branches.forEach(branch => {
        if (branch.finished) {
          ctx.beginPath();
          ctx.moveTo(branch.startX, branch.startY);
          ctx.quadraticCurveTo(branch.controlX, branch.controlY, branch.targetX, branch.targetY);
          ctx.strokeStyle = branch.depth < 3 ? config.branchColor : config.accentBranchColor;
          ctx.lineWidth = branch.width;
          ctx.lineCap = 'round';
          ctx.shadowColor = branch.depth < 3 ? config.branchColor : config.accentBranchColor;
          ctx.shadowBlur = branch.depth < 3 ? 8 : 4;
          ctx.stroke();
          ctx.shadowBlur = 0;
        }
      });

      // Draw neurons
      neurons.forEach(neuron => {
        ctx.beginPath();
        ctx.arc(neuron.x, neuron.y, neuron.radius, 0, Math.PI * 2);
        ctx.fillStyle = '#fff';
        ctx.shadowColor = '#fff';
        ctx.shadowBlur = 10;
        ctx.fill();
        ctx.shadowBlur = 0;
      });

      // Draw synapses
      synapses.forEach(synapse => synapse.draw(time / 1000));

      // Draw pulses
      pulses = pulses.filter(pulse => pulse.update());
      pulses.forEach(pulse => pulse.draw());

      // Vignette effect
      const vignette = ctx.createRadialGradient(
        width / 2, height / 2, 300,
        width / 2, height / 2, 500
      );
      vignette.addColorStop(0, 'rgba(0, 0, 0, 0)');
      vignette.addColorStop(1, 'rgba(0, 0, 0, 0.7)');
      ctx.fillStyle = vignette;
      ctx.fillRect(0, 0, width, height);

      // Scanlines
      ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
      for (let y = 0; y < height; y += 2) {
        ctx.fillRect(0, y, width, 1);
      }

      animationId = requestAnimationFrame(render);
    }

    // Setup GUI
    function setupGUI() {
      const gui = new dat.GUI({ autoPlace: true });
      gui.domElement.style.position = 'fixed';
      gui.domElement.style.top = '20px';
      gui.domElement.style.right = '20px';
      gui.domElement.style.zIndex = '1000';
      gui.domElement.style.maxWidth = '300px';
      gui.domElement.style.fontFamily = 'Segoe UI, Tahoma, Geneva, Verdana, sans-serif';

      const growthFolder = gui.addFolder('Growth');
      growthFolder.add(config, 'neuronCount', 1, 10).name('Neuron Count').onChange(regenerate);
      growthFolder.add(config, 'branchSpeed', 0.5, 3).name('Branch Speed').onChange(regenerate);
      growthFolder.add(config, 'maxBranchDepth', 3, 10).name('Max Branch Depth').onChange(regenerate);
      growthFolder.add(config, 'branchSplitChance', 0, 1).name('Split Chance').onChange(regenerate);
      growthFolder.add(config, 'branchCurvature', 0, 2).name('Branch Curvature').onChange(regenerate);
      growthFolder.add(config, 'maxBranchLength', 50, 200).name('Max Branch Length').onChange(regenerate);

      const synapsesFolder = gui.addFolder('Synapses');
      synapsesFolder.add(config, 'synapseThreshold', 20, 80).name('Distance Threshold').onChange(regenerate);
      synapsesFolder.add(config, 'synapseGlow', 5, 30).name('Glow Strength');

      const pulsesFolder = gui.addFolder('Pulses');
      pulsesFolder.add(config, 'pulseSpeed', 1, 10).name('Speed');
      pulsesFolder.add(config, 'pulseFrequency', 0.005, 0.1).name('Frequency');
      pulsesFolder.add(config, 'pulseBrightness', 0.5, 2).name('Brightness');

      const visualsFolder = gui.addFolder('Visuals');
      visualsFolder.addColor(config, 'backgroundColor').name('Background Color').onChange(regenerate);
      visualsFolder.addColor(config, 'branchColor').name('Branch Color').onChange(regenerate);
      visualsFolder.addColor(config, 'accentBranchColor').name('Accent Branch Color').onChange(regenerate);
      visualsFolder.addColor(config, 'synapseColor').name('Synapse Color').onChange(regenerate);
      visualsFolder.addColor(config, 'pulseColor').name('Pulse Color').onChange(regenerate);

      const buttonsFolder = gui.addFolder('Controls');
      buttonsFolder.add(config, 'regenerateNetwork').name('Regenerate');
      buttonsFolder.add(config, 'clearCanvas').name('Clear');
      buttonsFolder.add(config, 'pauseResume').name('Pause/Resume');

      growthFolder.open();
    }

    // Initialize
    function init() {
      initNeurons();
      growBranches();
      setupGUI();
      render(0);
    }

    // Start simulation
    init();
  </script>
</body>
</html>"}
